// Wazuh -> normalized alert. Accepts the raw integrator payload,
// {alert:{...}}, {alerts:[...]}, or a bare array of alerts.
const flatten = (b) => {
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.alerts)) return b.alerts;
  if (b && b.alert && typeof b.alert === 'object') return [b.alert];
  return [b || {}];
};

const WINDOW_MIN = 10;          // suppression window for repeat alerts
const MAX_ALERT_CHARS = 8000;   // cap the JSON sent to the LLM (context budget)
const out = [];

// Single source of truth for severity; the ARGUS prompt uses the same scale.
const severityOf = (l) => l >= 12 ? 'critical' : l >= 8 ? 'high' : l >= 4 ? 'medium' : 'low';

// Instruction-like text inside log fields is attacker-controlled and aimed at
// the LLM (prompt injection). Flag it deterministically; do not trust the model.
const INJECTION_RE = /(ignore|disregard|forget)[\s_\-]+(all[\s_\-]+)?(the[\s_\-]+)?(previous|prior|above|earlier)[\s_\-]+(instructions?|prompts?|rules)|system[\s_\-]*(note|prompt|message|override)\s*:|verdict[\s_\-]+(must|should)[\s_\-]+be|you[\s_\-]+are[\s_\-]+now|new[\s_\-]+instructions|as[\s_\-]+an[\s_\-]+ai/i;

// Benchmark overrides (_bench: {model, tag, run}) are honoured only in manual
// (test) runs, so the production webhook can never choose the model.
const manual = $execution.mode === 'test';

for (const item of $input.all()) {
  const body = item.json.body !== undefined ? item.json.body : item.json;
  for (const raw of flatten(body)) {
    const { _bench, ...a } = raw || {};
    const bench = manual && _bench && typeof _bench === 'object' ? _bench : null;
    const rule  = a.rule  || {};
    const agent = a.agent || {};
    const data  = a.data  || {};
    const mitre = rule.mitre || {};
    const level = Number(rule.level != null ? rule.level : 0);
    const ruleId  = String(rule.id  != null ? rule.id  : 'unknown');
    const agentId = String(agent.id != null ? agent.id : '000');
    const bucket = Math.floor(Date.now() / (WINDOW_MIN * 60 * 1000));
    const fullJson = JSON.stringify(a);
    let alertJson = fullJson;
    if (alertJson.length > MAX_ALERT_CHARS) alertJson = alertJson.slice(0, MAX_ALERT_CHARS) + ' ...[truncated]';

    out.push({ json: {
      received_at: new Date().toISOString(),
      timestamp: a.timestamp || null,
      level,
      severity: severityOf(level),
      rule_id: ruleId,
      rule_description: rule.description || 'No description',
      rule_groups: rule.groups || [],
      mitre_id: mitre.id || [],
      mitre_tactic: mitre.tactic || [],
      mitre_technique: mitre.technique || [],
      agent_id: agentId,
      agent_name: agent.name || 'unknown',
      agent_ip: agent.ip || null,
      manager: (a.manager && a.manager.name) || null,
      location: a.location || null,
      src_ip: data.srcip || a.srcip || null,
      dst_user: data.dstuser || null,
      full_log: a.full_log || null,
      injection_suspected: INJECTION_RE.test(fullJson),
      dedupe_key: bench
        ? ['bench', bench.model || 'default', bench.run || Date.now(), ruleId, agentId].join(':')
        : ruleId + ':' + agentId + ':' + bucket,
      bench,
      alert_json: alertJson,
      alert: a,
    }});
  }
}

return out;

